import os
import tanium


config_file = "/etc/samba/smb.conf"

smb_check_list=["workgroup","security","client min protocol","client max protocol","encrypt passwords","smb encrypt","smb signing"]

if os.path.isfile(config_file) == True:
    try:
        with open(config_file,'r') as file:
            for line in file:
                if "=" in line:
                    smb_config=line.split("=")

                    if smb_config[0].strip() in smb_check_list:
                        output=smb_config[0].strip()+"|"+smb_config[1].strip()
                        print(output)
                        tanium.results.add(output)

    except:
        import traceback
        print(traceback.format_exc())
        tanium.results.add(traceback.format_exc())
else:
    message_out="File not found : " + config_file
    print(message_out)
    tanium.results.add(message_out)
